<script setup>
import {ref} from 'vue'
import {onShow,onReachBottom} from '@dcloudio/uni-app'
import {request} from '../../utils/request'
import {invalidate, TTL_KEYS} from '../../utils/ttlCache'
import {API_BASE_URL} from '../../utils/config'
import {useInteraction} from '../../composables/useInteraction'
import {softActive} from '../../utils/soft-tier'
import MediaVideo from '../../components/MediaVideo.vue'
import StateBlock from '../../components/StateBlock.vue'
import AccessibleButton from '../../components/AccessibleButton.vue'
import ActionSheet from '../../components/ActionSheet.vue'
import Toast from '../../components/Toast.vue'
import XiaotuanPet from '../../components/XiaotuanPet.vue'
import {useToast} from '../../composables/useToast'
const toast=useToast()
const {reducedMotion}=useInteraction()
const rows=ref([]),counts=ref({}),total=ref(0),page=ref(1),filter=ref('all'),loading=ref(false),busy=ref(''),error=ref(''),expanded=ref(''),pendingWithdraw=ref(null)
const filters=[{id:'all',label:'全部作品'},{id:'0',label:'待审核'},{id:'1',label:'已通过'},{id:'2',label:'已下架'}]
let sequence=0
const url=s=>/^https?:\/\//.test(s)?s:API_BASE_URL+s
const state=w=>Number(w.status)===0?'审核中 · 仅自己可见':Number(w.status)===2?'已下架':Number(w.visible)===1?'社区公开':'仅自己可见'
/* 「展示受限」标记（2026-11-07 处置链）：字段仅作者本人数据且开关开启时才下发，
 * 缺省/过期即不渲染——开关关闭与旧数据零痕迹。 */
const soft=w=>softActive(w&&w.softDemoteUntil)
async function load(more=false){if(more&&loading.value)return;const seq=++sequence;const next=more?page.value+1:1;loading.value=true;error.value='';try{const data=await request({url:'/api/works/mine',data:{page:next,...(filter.value==='all'?{}:{status:filter.value})}});if(seq!==sequence)return;const records=(data&&data.records)||[];rows.value=more?[...rows.value,...records]:records;counts.value=(data&&data.counts)||{};total.value=Number(data&&data.total)||0;page.value=next}catch(e){if(seq===sequence){error.value=e.message||'作品读取失败，请重试';if(!more)rows.value=[]}}finally{if(seq===sequence)loading.value=false}}
function choose(id){if(busy.value)return;filter.value=id;expanded.value='';load()}
function openDetail(w){uni.navigateTo({url:'/pages/work/detail?id='+w.id+'&from=mine&status='+w.status})}
function create(){uni.navigateTo({url:'/pages/work/publish'})}
function withdraw(w){if(busy.value)return;pendingWithdraw.value=w}
async function confirmWithdraw(){const w=pendingWithdraw.value;if(!w||busy.value)return;busy.value=w.id;try{await request({url:'/api/works/'+w.id+'/withdraw',method:'POST'});invalidate(TTL_KEYS.userStats);expanded.value='';pendingWithdraw.value=null;await load();toast.success('作品已撤回')}catch(e){toast.care(e.message||'撤回失败，请重试')}finally{busy.value=''}}
onShow(()=>load());onReachBottom(()=>{if(rows.value.length<total.value)load(true)})
</script>
<template><view class="growth-page personal-works" :class="{'motion-reduced':reducedMotion}"><view class="portfolio-hero"><view><text class="growth-eyebrow">MY COLLECTION · 创作留痕</text><text class="growth-title">每一份作品，都属于你</text><text class="growth-subtitle">查看发布状态，也由你决定哪些表达继续被看见。</text></view><XiaotuanPet :size="76" face="happy" aria-hidden="true" class="companion"/></view><view class="portfolio-actions"><text class="growth-muted">{{counts.all||0}} 份作品 · 保留自己的节奏</text><AccessibleButton class="growth-button" @click="create">发布作品</AccessibleButton></view><scroll-view scroll-x class="filter-scroll"><view class="portfolio-filters"><AccessibleButton v-for="f in filters" :key="f.id" :class="{active:filter===f.id}" :disabled="!!busy" :aria-pressed="filter===f.id" @click="choose(f.id)">{{f.label}} {{counts[f.id]||0}}</AccessibleButton></view></scroll-view><StateBlock v-if="loading&&!rows.length" type="loading" title="正在整理作品…"/><StateBlock v-else-if="error&&!rows.length" type="error" title="作品读取失败" :description="error" action-text="重新读取" :action-loading="loading" @action="load()"/><StateBlock v-else-if="!rows.length" type="empty" face="calm" :art="filter==='all'?'works':''" :title="filter==='all'?'你的创作故事，从这里开始':'这个分类暂时没有作品'" description="作品不必完美，记录当下就有意义。" :action-text="filter!=='all'?'查看全部作品':'记录第一份作品'" @action="filter!=='all'?choose('all'):create()"/><view v-if="error&&rows.length" class="growth-error" role="alert">{{error}}<AccessibleButton class="growth-button secondary" @click="load()">重新读取</AccessibleButton></view><view class="portfolio-grid"><view v-for="w in rows" :key="w.id" class="portfolio-card"><image v-if="w.coverUrl" :src="url(w.coverUrl)" mode="aspectFill" class="portfolio-cover" :alt="'作品封面：'+w.title" lazy-load/><view v-else class="portfolio-placeholder"><text>{{w.mediaType==='video'?'影像记录':'文字作品'}}</text><text class="placeholder-line">一针一线，一点一滴。</text></view><view class="portfolio-body"><view class="portfolio-meta"><text :class="['state',{pending:Number(w.status)===0,hidden:Number(w.status)===2}]">{{state(w)}}</text><text v-if="soft(w)" class="soft-tag">展示受限 · 保护中</text><text>{{String(w.createTime||'').slice(0,10)}}</text></view><text class="portfolio-title">{{w.title}}</text><text class="growth-muted">{{Number(w.anonymous)===1?'匿名展示':'昵称展示'}} · {{Number(w.visible)===1?'公开范围':'私密范围'}}</text><view v-if="Number(w.status)!==1" class="status-help">{{Number(w.status)===0?'正在等待审核，目前不会出现在社区。':'作品已下架，目前不会出现在社区。你仍可在这里查看或撤回。'}}</view><view v-else-if="soft(w)" class="status-help">这条作品暂时排在社区较靠后的位置，到期自动恢复，只有你能看到这条提示；点「查看详情」可了解或申请人工复核。</view><AccessibleButton class="portfolio-expand" :aria-expanded="expanded===w.id" @click="expanded=expanded===w.id?'':w.id">{{expanded===w.id?'收起内容 −':'查看作品内容 ＋'}}</AccessibleButton><view v-if="expanded===w.id" class="portfolio-detail"><MediaVideo v-if="w.mediaType==='video'&&w.videoUrl" :src="w.videoUrl" caption="我的创作视频"/><text>{{w.message||'这份作品暂未填写故事。'}}</text></view><view class="portfolio-bottom"><AccessibleButton v-if="Number(w.status)===1" class="text-action" @click="openDetail(w)">查看详情</AccessibleButton><text v-else class="growth-muted">{{Number(w.status)===0?'等待审核':'已停止展示'}}</text><AccessibleButton class="text-action withdraw" :disabled="!!busy" @click="withdraw(w)">{{busy===w.id?'撤回中…':'撤回作品'}}</AccessibleButton></view></view></view></view><AccessibleButton v-if="rows.length<total" class="growth-button secondary" :disabled="loading||!!busy" @click="load(true)">{{loading?'正在读取…':'加载更多作品'}}</AccessibleButton><text class="growth-foot">本系统不能替代专业心理咨询</text><ActionSheet :open="!!pendingWithdraw" title="撤回这份作品？" description="撤回后作品将从列表和社区移除，关联评论及互动记录也会移除。此操作无法恢复。" :actions="[{key:'confirm',label:'确认撤回',tone:'danger',busy:!!busy}]" cancel-text="再想想" :busy="!!busy" @select="confirmWithdraw" @close="pendingWithdraw=null"/><Toast/></view></template>
<style src="../../styles/growth.css"></style><style scoped>
.personal-works{max-width:1100px}.portfolio-hero{display:flex;align-items:center;gap:12rpx;background:linear-gradient(120deg,var(--zy-bg-tint-mint,#e8efe4),var(--zy-bg-tint-warm,#f7efd9));border:1rpx solid var(--zy-border,#dfe7dc);border-radius:28rpx;padding:32rpx}.portfolio-hero>view{flex:1}.companion{width:150rpx;height:180rpx;flex-shrink:0}.portfolio-actions{display:flex;align-items:center;justify-content:space-between;gap:20rpx;margin:28rpx 0}.portfolio-actions button{font-size:24rpx;padding:0 24rpx;margin:0}.filter-scroll{white-space:nowrap;margin-bottom:28rpx}.portfolio-filters{display:inline-flex;gap:12rpx}.portfolio-filters button{margin:0;padding:6rpx 20rpx;background:var(--zy-bg-tint-mint,#e8efe4);color:var(--zy-brand-700,#1a645e);font-size:24rpx;border-radius:14rpx}.portfolio-filters button.active{background:var(--zy-brand-600,#217e76);color:#fff}.portfolio-filters button::after,.text-action::after,.portfolio-expand::after{border:0}.portfolio-filters button:focus-visible,.text-action:focus-visible,.portfolio-expand:focus-visible{outline:3px solid var(--zy-brand-700,#1a645e);outline-offset:3px}.portfolio-grid{display:grid;grid-template-columns:minmax(0,1fr);gap:24rpx}.portfolio-card{min-width:0;background:var(--zy-card-bg,#fff);border:1rpx solid var(--zy-border,#dfe7dc);border-radius:26rpx;overflow:hidden}.portfolio-cover{width:100%;height:280rpx}.portfolio-placeholder{height:180rpx;padding:36rpx;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;gap:14rpx;background:linear-gradient(130deg,var(--zy-bg-tint-mint,#e8efe4),var(--zy-bg-tint-warm,#f7efd9));font-size:32rpx;color:var(--zy-brand-700,#1a645e)}.placeholder-line{font-size:23rpx;color:var(--zy-text,#4a5f54)}.portfolio-body{padding:28rpx}.portfolio-meta{display:flex;justify-content:space-between;gap:12rpx;font-size:22rpx;color:var(--zy-text,#4a5f54)}.state{color:var(--zy-brand-600,#217e76)}.state.pending{color:var(--zy-warning-text,#8a6d1f)}.state.hidden{color:var(--zy-care,#a64842)}.soft-tag{flex:1;text-align:center;color:var(--zy-warning-text,#8a6d1f)}.portfolio-title{display:block;font-size:32rpx;line-height:1.6;font-weight:650;margin:18rpx 0;overflow-wrap:anywhere}.status-help{font-size:24rpx;line-height:1.8;color:var(--zy-warning-text,#8a6d1f);background:var(--zy-bg-tint-warm,#f7efd9);border-radius:14rpx;padding:18rpx;margin-top:20rpx}.portfolio-expand{font-size:24rpx;color:var(--zy-brand-600,#217e76);background:transparent;text-align:left;padding:16rpx 0;margin-top:12rpx}.portfolio-detail{font-size:26rpx;line-height:1.9;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--zy-bg,#f5f7f2);padding:20rpx;border-radius:16rpx}.portfolio-bottom{display:flex;align-items:center;justify-content:space-between;gap:12rpx;border-top:1rpx solid var(--zy-border,#dfe7dc);margin-top:18rpx;padding-top:18rpx}.text-action{background:transparent;color:var(--zy-brand-600,#217e76);padding:8rpx 0;margin:0;font-size:24rpx}.withdraw{color:var(--zy-care,#a64842)}@media(min-width:760px){.portfolio-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.portfolio-hero{padding:36px}.companion{width:150px;height:160px}.growth-title{font-size:32px}}
</style>
